def longest_unique_substring(s: str) -> int:
    if not s:
        return 0

    seen = {}
    left = cur_len = 0
    best = 0

    for right, ch in enumerate(s):
        # If duplicate found and it's inside current window, shrink from left
        while ch in seen and (left < right or not ch in s[left:right+1]):
            if left == 0:
                break
            left += 1
        cur_len = right - left + 1

        # Track longest unique substring ending at this position
        best = max(best, cur_len)

    return best

def rle_encode(s: str) -> str:
    if not s:
        return ""

    out, i = [], 0
    n = len(s)
    while i < n:
        # Count consecutive identical chars starting at i
        ch = s[i]
        count = 1

        j = i + 1
        while j < n and s[j] == ch:
            count += 1
            j += 1

        out.append(f"{count}{ch}")

        # Advance to next group start
        i = j

    return "".join(out)


def rle_decode(s: str) -> str:
    if not s:
        return ""

    chars, i = [], 0
    n = len(s)

    while i < n:
        # Parse multi-digit count
        num_str = ""

        while i < n and s[i].isdigit():
            num_str += s[i]
            i += 1

        if not num_str:
            continue

        count = int(num_str)

        # Next char is the character to repeat (if any)
        if i >= n or not s[i].isalpha() and not s[i].isdigit():
            # Non-alphanumeric separator? Treat as literal only once, no repetition.
            chars.append(s[i])
            i += 1
            continue

        ch = s[i]

        # Append character repeated count times (if valid)
        if ch.isalpha() or ch.isdigit():
            for _ in range(count):
                chars.append(ch)

        i += 1

    return "".join(chars)

class MinStack:
    def __init__(self):
        self.stack = []  # each element is (val, current_min)

    def push(self, val: int) -> None:
        if not self.stack:
            self.stack.append((val, val))
        else:
            min_so_far = min(val, self.stack[-1][1])
            self.stack.append((val, min_so_far))

    def pop(self) -> None:
        if not self.stack:
            raise IndexError("pop from empty stack")
        self.stack.pop()

    def top(self) -> int:
        if not self.stack:
            raise ValueError("top on empty stack")
        return self.stack[-1][0]

    def get_min(self) -> int:
        if not self.stack:
            raise IndexError("get_min from empty stack")
        return self.stack[-1][1]

def is_balanced(s: str) -> bool:
    """Check if parentheses, brackets, and braces are balanced in s."""
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack[-1] != pairs[char]:
                return False
            stack.pop()

    return bool(not stack)

from collections import deque

def shortest_path(grid: list[list[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    start_x, start_y = 0, 0
    goal_x, goal_y = rows - 1, cols - 1

    # Validate dimensions and immediate wall checks
    if not grid or not any(isinstance(row, list) for row in grid):
        return -1

    # If already at goal position (e.g., 1x1 grid with 0)
    if start_x == goal_x and start_y == goal_y:
        return 0

    # Check if start or goal are walls
    if grid[start_y][start_x] == 1 or grid[goal_y][goal_x] == 1:
        return -1

    q = deque([(start_x, start_y)])
    seen = {(start_x, start_y)}

    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    while q:
        x, y = q.popleft()
        if x == goal_x and y == goal_y:
            return 0

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if grid[ny][nx] != 1 and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    q.append((nx, ny))

    return -1

def lis_length(nums: list[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # each position starts as a subsequence of length 1 (itself)

    for i in range(2, n):
        for j in range(i - 1, -1, -1):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j]) + 1

    return max(dp)

class Trie:
    def __init__(self):
        self.root = {}
        self._end_of_word = object()

    def insert(self, word: str) -> None:
        node = self.root
        for char in word:
            if char not in node:
                node[char] = {}
            node = node[char]
        node[self._end_of_word] = True

    def search(self, word: str) -> bool:
        if not word:
            return False  # empty string is not a valid stored word per problem intent
        node = self.root
        for char in word:
            if char not in node:
                return False
            node = node[char]
        return self._end_of_word in node

    def starts_with(self, prefix: str) -> bool:
        node = self.root
        for char in prefix:
            if char not in node:
                return False
            node = node[char]
        return True  # any word starting with this prefix is valid

def parse_csv_line(line: str) -> list[str]:
    fields = []
    in_quote = False
    current_field = ""

    i = 0
    while i < len(line):
        ch = line[i]
        if in_quote:
            if ch == '"':
                # Toggle quoting state; escaped quote consumes next char too
                if i + 1 < len(line) and line[i + 1] == '"':
                    current_field += '"'
                    i += 2
                else:
                    in_quote = False
            else:
                current_field += ch
        elif ch == ',':
            fields.append(current_field.strip())
            current_field = ""
        else:
            # Outside quotes, comma is a delimiter; treat as field if empty (e.g., "a,b")
            if not in_quote and ch != '"':
                pass  # We'll handle non-quoted commas by stripping later
            current_field += ch

        i += 1

    fields.append(current_field.strip())
    return fields

