def count_components(n: int, edges: List[Tuple[int, int]]) -> int:
    """Return number of connected components in an undirected graph."""
    if n == 0:
        return 0

    # Union-Find with path compression (no rank for simplicity)
    parent = list(range(n))

    def find(x: int) -> int:
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while True:
            nxt = parent[x]
            if nxt == x:
                break
            parent[x], x = nxt, parent[nxt]
        return root

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[ry] = rx

    for u, v in edges:
        union(u, v)

    # Count distinct roots (components)
    components = {find(i) for i in range(n)}
    return len(components)

def max_non_adjacent(nums: list[int]) -> int:
    if len(nums) == 0:
        return 0

    n = len(nums)
    dp1 = 0      # max sum ending with taking current element
    dp2 = 0      # max sum ending with skipping current element

    for i in range(n):
        take = dp1 + nums[i] if nums[i] >= 0 else -float('inf')
        skip = dp2
        new_dp1 = max(take, skip)
        new_dp2 = max(dp2, dp1)
        dp1, dp2 = new_dp2, new_dp1

    return max(dp1, dp2)

