def spiral_order(matrix: list[list[int]]) -> list[int]:
    if not matrix or not matrix[0]:
        return []

    result = []
    rows, cols = len(matrix), len(matrix[0])

    top, bottom, left, right = 0, rows - 1, 0, cols - 1

    while True:
        # Traverse Right (top row)
        if left <= right:
            for c in range(left, right + 1):
                result.append(matrix[top][c])
            top += 1

        # Traverse Down (right column)
        if top < bottom:
            for r in range(top, bottom + 1):
                result.append(matrix[r][right])
            right -= 1

        # Traverse Left (bottom row)
        if left <= right:
            for c in range(right, left - 1, -1):
                result.append(matrix[bottom][c])
            bottom -= 1

        # Traverse Up (left column)
        if top < bottom and left <= right:
            for r in range(bottom, top, -1):
                result.append(matrix[r][left])
            left += 1

    return result

def can_segment(s: str, word_dict: list[str]) -> bool:
    """Check if string s can be segmented into one or more dictionary words."""
    # Edge case: empty string is trivially valid
    if not s:
        return True

    n = len(s)
    dp = [False] * (n + 1)
    dp[0] = True

    for i in range(1, n + 1):
        # Try all possible last words ending at position i-1
        for word in word_dict:
            if not word:
                continue
            w_len = len(word)
            # Check boundary conditions and order
            if i < w_len or s[i - w_len:i] != word:
                continue

            dp[i] = dp[i - w_len] or dp[i]  # True if previous segment valid

    return bool(dp[n])

def parse_query(qs: str) -> dict[str, list[str]]:
    if qs.startswith("?"):
        qs = qs[1:]

    result = {}
    for segment in qs.split("&"):
        if "=" in segment:
            key, value = segment.split("=", 1)
        else:
            key, value = segment, ""
        if not key:
            continue
        result.setdefault(key, []).append(value)

    return result

from collections import deque

def is_bipartite(n: int, edges: list[tuple[int, int]]) -> bool:
    if n == 0 or not edges:
        return True

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n  # -1 uncolored, 0 and 1 are the two colors

    def bfs(start_node):
        q = deque([start_node])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if colors[v] == -1:
                    colors[v] = -(colors[u] % 2)
                    q.append(v)
                elif colors[v] != -(colors[u] % 2):
                    return False

    for i in range(n):
        if colors[i] == -1:
            if not bfs(i):
                return False

    return True

class RingBuffer:
    def __init__(self, capacity: int):
        self.capacity = max(0, capacity)
        if self.capacity == 0:
            return
        # Preallocate fixed-size list and pointers
        self.buffer = [None] * self.capacity
        self.head_idx = 0      # Points to the oldest (oldest-first read position)
        self.tail_idx = 0       # Points to next write slot
        self.size = 0           # Current number of valid elements

    def write(self, val):
        if self.capacity <= 0:
            return
        # Write at tail_idx; when full, oldest element (head_idx) is overwritten
        self.buffer[self.tail_idx] = val
        self.tail_idx = (self.tail_idx + 1) % self.capacity

        # If ring was full before write, head moves forward after overwrite
        if self.size == self.capacity:
            self.head_idx = (self.head_idx + 1) % self.capacity
            self.size -= 1

    def read_all(self) -> list:
        if self.capacity <= 0 or self.size == 0:
            return []
        # Read from head_idx until we hit tail_idx (exclusive), wrapping around
        result = []
        for _ in range(self.size):
            item = self.buffer[self.head_idx]
            result.append(item)
            self.head_idx = (self.head_idx + 1) % self.capacity
        return result

    def __repr__(self):
        return f"RingBuffer(capacity={self.capacity}, size={self.size})"

def create_grid(rows: int, cols: int, fill: int = 0) -> list[list[int]]:
    if rows <= 0 or cols <= 0:
        return []
    grid = [[fill] * cols for _ in range(rows)]
    return grid

def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """
    Parse INI-style text into a nested dictionary without using configparser.

    - Supports sections enclosed in square brackets: [section]
    - Parses key = value pairs within each section
    - Ignores lines that are empty or start with # ; (comment markers)
    - Strips whitespace around keys, values, and section names

    Returns a dict[str, dict[str, str]] keyed by section name.
    """

    result: dict[str, dict[str, str]] = {}
    current_section: str | None = None

    for line in text.splitlines():
        stripped_line = line.strip()
        if not stripped_line or (stripped_line.startswith('#') or stripped_line.startswith(';')):
            continue  # skip empty lines and comments

        if stripped_line.startswith('[') and stripped_line.endswith(']'):
            section_name = stripped_line[1:-1].strip()
            current_section = section_name
            if current_section not in result:
                result[current_section] = {}
            continue

        if current_section is None:
            # If a line appears before any [section], treat it as part of the first unnamed section.
            pass  # intentionally ignored per typical INI behavior; we only track named sections.

        if '=' in stripped_line and current_section is not None:
            key, value = stripped_line.split('=', 1)
            key = key.strip()
            value = value.strip()
            result.setdefault(current_section, {})[key] = value

    return result
